#include "native/providers/moe_accumulator/q1_moe_hawkeye_bf16_accumulator.h"
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <stdexcept>
#include <vector>
namespace ref=qrt_q1_moe_hawkeye;
void require(bool x,const char* message){if(!x)throw std::runtime_error(message);}
std::vector<uint16_t> read(const char* path,size_t count){
 std::ifstream f(path,std::ios::binary|std::ios::ate);require(f&&f.tellg()==std::streamoff(count*2u),"tensor span");
 std::vector<uint16_t> result(count);f.seekg(0);f.read(reinterpret_cast<char*>(result.data()),count*2u);require(bool(f),"tensor read");return result;
}
float f32(uint16_t x){const uint32_t bits=uint32_t(x)<<16u;float v;std::memcpy(&v,&bits,4);return v;}
uint16_t bf16(float f){uint32_t bits;std::memcpy(&bits,&f,4);return uint16_t((bits+32767u+((bits>>16u)&1u))>>16u);}
float rz(double x){float y=float(x);if(std::abs(double(y))>std::abs(x))y=std::nextafter(y,0.0f);return y;}
int main(int argc,char** argv){try{
 require(argc==6,"inputs weights reference-or-dash rows width");
 const unsigned rows=std::stoul(argv[4]),width=std::stoul(argv[5]),groups=width/16u;
 require(width&&!(width%16u)&&rows,"shape");
 const auto input=read(argv[1],size_t(7169u)*width),weight=read(argv[2],size_t(rows)*width);
 const bool external=std::strcmp(argv[3],"-")!=0;
 const auto golden=external?read(argv[3],size_t(8192u)*rows):std::vector<uint16_t>{};
 constexpr unsigned samples=65536u;const uint64_t cells=uint64_t(8192u)*rows;
 std::cout<<"cell,original,mathematical,group_rz,alignment_delta,truncation_delta,carry_half_ulp_proxy,l1,cauchy,gb10_bf16\n"<<std::setprecision(17);
 for(unsigned sample=0u;sample<samples;++sample){
  // Odd affine permutation gives unique, input-independent full-shape cells.
  const uint32_t cell=uint32_t((uint64_t(sample)*2654435761ull+1013904223ull)%cells);
  const unsigned token=cell/rows,row=cell%rows,source_token=token<7169u?token:token-7169u;
  const uint16_t* a=input.data()+size_t(source_token)*width;const uint16_t* b=weight.data()+size_t(row)*width;
  ref::Value carry{0u,-133,false};double mathematical=0,align_delta=0,trunc_delta=0,proxy=0,l1=0,aa=0,bb=0;float grouped=0;
  for(unsigned group=0;group<groups;++group){
   ref::Value terms[17];terms[0]=carry;double exact_group=0;
   for(unsigned i=0;i<16u;++i){const unsigned k=group*16u+i;const double x=f32(a[k]),w=f32(b[k]);
    exact_group+=x*w;l1+=std::abs(x*w);aa+=x*x;bb+=w*w;terms[i+1u]=ref::multiply_bf16(a[k],b[k],-133);
   }
   mathematical+=exact_group;grouped=rz(double(grouped)+exact_group);
   int maximum=-133;for(const auto& value:terms)maximum=std::max(maximum,int(value.exponent));
   int64_t aligned_integer=0;
   for(const auto& value:terms){const unsigned shift=unsigned(maximum-value.exponent);const uint64_t aligned=shift>=32u?0u:(uint64_t(value.significand)<<2u)>>shift;aligned_integer+=value.negative?-int64_t(aligned):int64_t(aligned);}
   const double before=double(ref::value_to_float(carry))+exact_group;
   const double aligned=std::ldexp(double(aligned_integer),maximum-25);
   const auto next=ref::group_sum<26,-133>(terms,17u);const double after=ref::value_to_float(next);
   align_delta+=aligned-before;trunc_delta+=after-aligned;
   if(after!=0.0){int e;std::frexp(std::abs(after),&e);proxy+=std::copysign(std::ldexp(0.5,e-24),after);}
   carry=next;
  }
  const float original=ref::value_to_float(carry);
  require(std::isfinite(original)&&std::isfinite(mathematical),"finite data");
  require(std::abs((double(original)-mathematical)-(align_delta+trunc_delta))<1e-9*(1+l1),"error decomposition");
  if(external)require(bf16(original)==golden[cell],"sampled original differs from GB10");
  std::cout<<cell<<','<<original<<','<<mathematical<<','<<grouped<<','<<align_delta<<','<<trunc_delta<<','<<proxy<<','<<l1<<','<<std::sqrt(aa*bb)<<','<<(external?int(golden[cell]):-1)<<'\n';
 }
 return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
